INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0013-0000-0000-000000000010','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Capture d''écran d''un SMS reçu de l''opérateur Orange : la consommation de données mobiles a atteint 90% du forfait mensuel.','2026-05-27 17:40:30.209527+02',NULL,'<svg width="100%" viewBox="0 0 680 660" role="img" xmlns="http://www.w3.org/2000/svg"><title>SMS Orange : forfait à 90%</title><desc>Écran de téléphone affichant un SMS de l''opérateur Orange indiquant que la consommation de données mobiles a atteint 90 pourcent du forfait mensuel.</desc><rect x="0" y="0" width="680" height="660" fill="#F5F5F7"/><rect x="170" y="40" width="340" height="600" rx="42" fill="#1A1A1A"/><rect x="180" y="80" width="320" height="560" rx="6" fill="#FFFFFF"/><rect x="280" y="50" width="120" height="26" rx="13" fill="#1A1A1A"/><circle cx="395" cy="63" r="4" fill="#2A2A2A"/><text x="200" y="108" font-family="Arial, sans-serif" font-size="14" font-weight="600" fill="#0F1839">9:42</text><g transform="translate(440, 96)"><rect x="0" y="0" width="3" height="8" rx="0.5" fill="#0F1839"/><rect x="5" y="-2" width="3" height="10" rx="0.5" fill="#0F1839"/><rect x="10" y="-4" width="3" height="12" rx="0.5" fill="#0F1839"/><rect x="15" y="-6" width="3" height="14" rx="0.5" fill="#0F1839"/></g><rect x="482" y="92" width="14" height="8" rx="2" fill="none" stroke="#0F1839" stroke-width="1"/><rect x="484" y="94" width="9" height="4" fill="#168F5B"/><rect x="180" y="124" width="320" height="44" fill="#FAFAFA"/><line x1="180" y1="168" x2="500" y2="168" stroke="#E5E5E7" stroke-width="0.5"/><path d="M 196 138 L 188 146 L 196 154" fill="none" stroke="#FF6B35" stroke-width="2" stroke-linecap="round"/><text x="210" y="151" font-family="Arial, sans-serif" font-size="13" fill="#FF6B35">Messages</text><text x="340" y="151" text-anchor="middle" font-family="Arial, sans-serif" font-size="15" font-weight="600" fill="#0F1839">Orange Info</text><g transform="translate(340, 200)"><circle cx="0" cy="0" r="24" fill="#FF6B35"/><text x="0" y="6" text-anchor="middle" font-family="Arial, sans-serif" font-size="18" font-weight="700" fill="#FFFFFF">O</text></g><text x="340" y="246" text-anchor="middle" font-family="Arial, sans-serif" font-size="13" font-weight="600" fill="#0F1839">Orange Info</text><text x="340" y="262" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" fill="#888888">SMS · 9:41</text><rect x="200" y="290" width="270" height="245" rx="14" fill="#E8E8ED"/><text x="216" y="316" font-family="Arial, sans-serif" font-size="12" font-weight="600" fill="#0F1839">Orange</text><text x="216" y="340" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">Bonjour,</text><text x="216" y="362" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">Vous avez utilisé</text><text x="216" y="378" font-family="Arial, sans-serif" font-size="12" font-weight="700" fill="#E1372F">90% de votre forfait</text><text x="216" y="394" font-family="Arial, sans-serif" font-size="12" font-weight="700" fill="#E1372F">internet mobile</text><text x="216" y="410" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">ce mois-ci.</text><text x="216" y="434" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">Pour éviter une</text><text x="216" y="450" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">coupure, rechargez</text><text x="216" y="466" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">votre forfait sur</text><text x="216" y="482" font-family="Arial, sans-serif" font-size="12" font-weight="600" fill="#1E3A8C">orange.fr/recharge</text><text x="216" y="506" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">Stop SMS au 38059</text><text x="216" y="522" font-family="Arial, sans-serif" font-size="11" fill="#888888">(gratuit)</text></svg>');
INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0013-0000-0000-000000000011','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Affiche annonçant un concert gratuit le samedi 12 juillet à 21h dans le parc municipal de la ville, organisé par la mairie.','2026-05-27 17:40:30.209527+02',NULL,'<svg width="100%" viewBox="0 0 680 800" role="img" xmlns="http://www.w3.org/2000/svg"><title>Affiche concert gratuit en plein air</title><desc>Affiche annonçant un concert d''été gratuit le samedi 12 juillet à 21h au parc municipal de la ville, organisé par la mairie.</desc><rect x="0" y="0" width="680" height="800" fill="#1E3A8C"/><rect x="40" y="40" width="600" height="720" fill="#FDF6E3" stroke="#0F1839" stroke-width="2"/><rect x="60" y="60" width="560" height="60" fill="#E1372F"/><text x="340" y="100" text-anchor="middle" font-family="Georgia, serif" font-size="32" font-weight="700" fill="#FFFFFF">CONCERT D''ÉTÉ</text><text x="340" y="180" text-anchor="middle" font-family="Arial, sans-serif" font-size="22" fill="#0F1839">en plein air, sous les étoiles</text><g transform="translate(180, 240)"><rect x="0" y="0" width="320" height="100" fill="#FFFFFF" stroke="#E1372F" stroke-width="3"/><text x="160" y="40" text-anchor="middle" font-family="Arial, sans-serif" font-size="18" font-weight="700" fill="#0F1839">SAMEDI 12 JUILLET</text><line x1="60" y1="55" x2="260" y2="55" stroke="#E1372F" stroke-width="1"/><text x="160" y="80" text-anchor="middle" font-family="Arial, sans-serif" font-size="32" font-weight="700" fill="#E1372F">à 21h00</text></g><g transform="translate(340, 380)"><circle cx="0" cy="0" r="48" fill="#E1372F"/><text x="0" y="-4" text-anchor="middle" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#FFFFFF">ENTRÉE</text><text x="0" y="20" text-anchor="middle" font-family="Arial, sans-serif" font-size="22" font-weight="700" fill="#FFFFFF">GRATUITE</text></g><text x="340" y="500" text-anchor="middle" font-family="Arial, sans-serif" font-size="20" fill="#0F1839">📍 Parc municipal — kiosque central</text><text x="340" y="540" text-anchor="middle" font-family="Arial, sans-serif" font-size="16" fill="#0F1839">Avenue des Tilleuls, 12 rue du Parc</text><line x1="140" y1="580" x2="540" y2="580" stroke="#0F1839" stroke-width="1" stroke-dasharray="4 4"/><text x="340" y="615" text-anchor="middle" font-family="Arial, sans-serif" font-size="14" fill="#5C6573">Trois groupes locaux à l''affiche</text><text x="340" y="635" text-anchor="middle" font-family="Arial, sans-serif" font-size="14" fill="#5C6573">Restauration sur place</text><text x="340" y="655" text-anchor="middle" font-family="Arial, sans-serif" font-size="14" fill="#5C6573">En cas de pluie : reporté au dimanche</text><rect x="60" y="700" width="560" height="40" fill="#0F1839"/><text x="340" y="725" text-anchor="middle" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#FFFFFF">Organisé par la mairie · plus d''infos : ville.fr/concerts</text></svg>');
