INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0013-0000-0000-000000000013','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Capture d''écran du site Doctolib pour le cabinet du docteur Bernard, médecin généraliste, montrant les créneaux disponibles : pas de disponibilité aujourd''hui, premier rendez-vous possible demain à 11h30.','2026-05-27 17:40:30.209527+02',NULL,'<svg width="100%" viewBox="0 0 680 540" role="img" xmlns="http://www.w3.org/2000/svg"><title>Recherche de rendez-vous Doctolib chez un médecin</title><desc>Capture d''écran du site Doctolib pour le cabinet du docteur Bernard, médecin généraliste, montrant les créneaux disponibles : pas de disponibilité aujourd''hui, premier rendez-vous possible demain à 11h30.</desc><rect x="0" y="0" width="680" height="540" fill="#F4F8FB"/><rect x="20" y="20" width="640" height="500" rx="8" fill="#FFFFFF" stroke="#D5DDE3" stroke-width="1"/><rect x="20" y="20" width="640" height="50" rx="8" fill="#FFFFFF"/><rect x="20" y="60" width="640" height="10" fill="#FFFFFF"/><line x1="20" y1="70" x2="660" y2="70" stroke="#D5DDE3" stroke-width="1"/><text x="40" y="52" font-family="Arial, sans-serif" font-size="20" font-weight="700" fill="#107ACA">doctolib</text><g transform="translate(560, 32)"><rect x="0" y="0" width="60" height="28" rx="14" fill="#107ACA"/><text x="30" y="18" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" font-weight="600" fill="#FFFFFF">Connexion</text></g><rect x="40" y="90" width="600" height="100" rx="6" fill="#F4F8FB"/><g transform="translate(60, 110)"><rect x="0" y="0" width="60" height="60" rx="30" fill="#D5DDE3"/><text x="30" y="38" text-anchor="middle" font-family="Arial, sans-serif" font-size="24" font-weight="700" fill="#5C6573">B</text></g><text x="140" y="130" font-family="Arial, sans-serif" font-size="18" font-weight="700" fill="#0F1839">Dr Bernard — Médecin généraliste</text><text x="140" y="152" font-family="Arial, sans-serif" font-size="13" fill="#5C6573">📍 24 rue Victor Hugo, 75011 Paris</text><text x="140" y="172" font-family="Arial, sans-serif" font-size="13" fill="#5C6573">Conventionné secteur 1 · Carte Vitale acceptée</text><text x="40" y="220" font-family="Arial, sans-serif" font-size="14" font-weight="600" fill="#0F1839">Prendre rendez-vous</text><g transform="translate(40, 240)"><rect x="0" y="0" width="120" height="40" rx="6" fill="#FFFFFF" stroke="#D5DDE3" stroke-width="1"/><text x="60" y="18" text-anchor="middle" font-family="Arial, sans-serif" font-size="10" font-weight="600" fill="#5C6573">AUJOURD''HUI</text><text x="60" y="33" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" font-weight="600" fill="#E1372F">complet</text></g><g transform="translate(170, 240)"><rect x="0" y="0" width="120" height="40" rx="6" fill="#107ACA"/><text x="60" y="18" text-anchor="middle" font-family="Arial, sans-serif" font-size="10" font-weight="600" fill="#FFFFFF">DEMAIN</text><text x="60" y="33" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" font-weight="600" fill="#FFFFFF">5 créneaux</text></g><g transform="translate(300, 240)"><rect x="0" y="0" width="120" height="40" rx="6" fill="#FFFFFF" stroke="#D5DDE3" stroke-width="1"/><text x="60" y="18" text-anchor="middle" font-family="Arial, sans-serif" font-size="10" font-weight="600" fill="#5C6573">APRÈS-DEMAIN</text><text x="60" y="33" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" font-weight="600" fill="#0F1839">8 créneaux</text></g><text x="40" y="320" font-family="Arial, sans-serif" font-size="13" font-weight="600" fill="#0F1839">Créneaux disponibles demain :</text><g transform="translate(40, 340)"><rect x="0" y="0" width="80" height="36" rx="4" fill="#FFFFFF" stroke="#107ACA" stroke-width="1.5"/><text x="40" y="22" text-anchor="middle" font-family="Arial, sans-serif" font-size="13" font-weight="600" fill="#107ACA">11h30</text></g><g transform="translate(130, 340)"><rect x="0" y="0" width="80" height="36" rx="4" fill="#FFFFFF" stroke="#107ACA" stroke-width="1.5"/><text x="40" y="22" text-anchor="middle" font-family="Arial, sans-serif" font-size="13" font-weight="600" fill="#107ACA">14h00</text></g><g transform="translate(220, 340)"><rect x="0" y="0" width="80" height="36" rx="4" fill="#FFFFFF" stroke="#107ACA" stroke-width="1.5"/><text x="40" y="22" text-anchor="middle" font-family="Arial, sans-serif" font-size="13" font-weight="600" fill="#107ACA">15h15</text></g><g transform="translate(310, 340)"><rect x="0" y="0" width="80" height="36" rx="4" fill="#FFFFFF" stroke="#107ACA" stroke-width="1.5"/><text x="40" y="22" text-anchor="middle" font-family="Arial, sans-serif" font-size="13" font-weight="600" fill="#107ACA">16h45</text></g><g transform="translate(400, 340)"><rect x="0" y="0" width="80" height="36" rx="4" fill="#FFFFFF" stroke="#107ACA" stroke-width="1.5"/><text x="40" y="22" text-anchor="middle" font-family="Arial, sans-serif" font-size="13" font-weight="600" fill="#107ACA">17h30</text></g><rect x="40" y="410" width="600" height="50" rx="6" fill="#FDECEB"/><text x="60" y="430" font-family="Arial, sans-serif" font-size="13" font-weight="600" fill="#E1372F">⚠ Annulez au moins 24h avant si vous ne pouvez pas venir.</text><text x="60" y="448" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">En cas d''urgence, contactez le 15 (SAMU) ou les urgences.</text></svg>');
INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0013-0000-0000-000000000020','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Capture d''écran d''un client de messagerie affichant un e-mail reçu de l''Alliance Française confirmant l''inscription à un cours de français niveau B1, le mardi à 18h, à partir du 15 septembre.','2026-05-27 17:40:30.209527+02',NULL,'<svg width="100%" viewBox="0 0 680 540" role="img" xmlns="http://www.w3.org/2000/svg"><title>Email confirmation inscription cours de français B1</title><desc>Capture d''écran d''un client de messagerie affichant un email reçu de l''Alliance Française confirmant l''inscription à un cours de français niveau B1, le mardi à 18h, à partir du 15 septembre.</desc><rect x="0" y="0" width="680" height="540" fill="#F1F3F4"/><rect x="20" y="20" width="640" height="500" rx="8" fill="#FFFFFF" stroke="#DADCE0" stroke-width="1"/><line x1="20" y1="76" x2="660" y2="76" stroke="#DADCE0" stroke-width="0.5"/><g transform="translate(40, 38)"><rect x="0" y="4" width="20" height="2" fill="#5F6368" rx="1"/><rect x="0" y="11" width="20" height="2" fill="#5F6368" rx="1"/><rect x="0" y="18" width="20" height="2" fill="#5F6368" rx="1"/></g><text x="80" y="55" font-family="Arial, sans-serif" font-size="20" font-weight="500" fill="#5F6368">Boîte de réception</text><g transform="translate(560, 32)"><rect x="0" y="0" width="32" height="32" rx="16" fill="#1A73E8"/><text x="16" y="22" text-anchor="middle" font-family="Arial, sans-serif" font-size="14" font-weight="600" fill="#FFFFFF">M</text></g><rect x="20" y="76" width="640" height="60" fill="#E8F0FE"/><line x1="20" y1="136" x2="660" y2="136" stroke="#DADCE0" stroke-width="0.5"/><g transform="translate(48, 95)"><path d="M 0 0 L 12 6 L 0 12 Z" fill="#FBBC04"/></g><g transform="translate(80, 95)"><circle cx="9" cy="9" r="9" fill="#1A73E8"/><text x="9" y="13" text-anchor="middle" font-family="Arial, sans-serif" font-size="10" font-weight="600" fill="#FFFFFF">A</text></g><text x="115" y="110" font-family="Arial, sans-serif" font-size="14" font-weight="600" fill="#202124">Alliance Française</text><text x="115" y="126" font-family="Arial, sans-serif" font-size="13" fill="#202124">Confirmation de votre inscription au cours de français B1</text><text x="600" y="110" text-anchor="end" font-family="Arial, sans-serif" font-size="12" fill="#5F6368">14:23</text><rect x="40" y="160" width="600" height="340" fill="#FFFFFF"/><line x1="40" y1="200" x2="640" y2="200" stroke="#DADCE0" stroke-width="0.5"/><text x="40" y="184" font-family="Arial, sans-serif" font-size="18" font-weight="600" fill="#202124">Confirmation de votre inscription au cours de français B1</text><g transform="translate(40, 220)"><circle cx="20" cy="20" r="20" fill="#1A73E8"/><text x="20" y="26" text-anchor="middle" font-family="Arial, sans-serif" font-size="16" font-weight="600" fill="#FFFFFF">A</text></g><text x="90" y="232" font-family="Arial, sans-serif" font-size="14" font-weight="600" fill="#202124">Alliance Française</text><text x="220" y="232" font-family="Arial, sans-serif" font-size="13" fill="#5F6368">&lt;inscriptions@alliance-francaise.fr&gt;</text><text x="90" y="252" font-family="Arial, sans-serif" font-size="13" fill="#5F6368">à moi</text><text x="40" y="290" font-family="Arial, sans-serif" font-size="14" fill="#202124">Madame, Monsieur,</text><text x="40" y="316" font-family="Arial, sans-serif" font-size="14" fill="#202124">Nous vous confirmons votre inscription au cours de français de</text><text x="40" y="334" font-family="Arial, sans-serif" font-size="14" fill="#202124">niveau <tspan font-weight="700" fill="#1A73E8">B1</tspan>. Les cours auront lieu tous les <tspan font-weight="700" fill="#1A73E8">mardis de 18h à 20h</tspan>,</text><text x="40" y="352" font-family="Arial, sans-serif" font-size="14" fill="#202124">à partir du <tspan font-weight="700" fill="#1A73E8">15 septembre</tspan>, en salle 204.</text><text x="40" y="382" font-family="Arial, sans-serif" font-size="14" fill="#202124">Merci de vous présenter dix minutes avant le début du premier</text><text x="40" y="400" font-family="Arial, sans-serif" font-size="14" fill="#202124">cours avec une pièce d''identité et le reçu de paiement.</text><text x="40" y="430" font-family="Arial, sans-serif" font-size="14" fill="#202124">Cordialement,</text><text x="40" y="452" font-family="Arial, sans-serif" font-size="14" fill="#202124">Le secrétariat de l''Alliance Française</text></svg>');
