INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0013-0000-0000-000000000023','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Capture d''écran du site officiel d''un musée affichant les tarifs : plein tarif 12 euros, tarif réduit 8 euros, gratuit pour les moins de 18 ans et le premier dimanche du mois.','2026-05-27 17:40:30.209527+02',NULL,'<svg width="100%" viewBox="0 0 680 620" role="img" xmlns="http://www.w3.org/2000/svg"><title>Site web du musée d''Art moderne — tarifs</title><desc>Capture d''écran du site officiel d''un musée affichant les tarifs : plein tarif 12 euros, tarif réduit 8 euros, gratuit pour les moins de 18 ans et le premier dimanche du mois.</desc><rect x="0" y="0" width="680" height="620" fill="#FAFAFA"/><rect x="20" y="20" width="640" height="580" rx="6" fill="#FFFFFF" stroke="#D5D5D5" stroke-width="1"/><rect x="20" y="20" width="640" height="60" fill="#0F1839"/><text x="40" y="56" font-family="Georgia, serif" font-size="20" font-weight="700" fill="#FFFFFF">MUSÉE D''ART MODERNE</text><text x="40" y="73" font-family="Arial, sans-serif" font-size="11" fill="#A8B0C5">de la Ville</text><g transform="translate(450, 30)"><text x="0" y="22" font-family="Arial, sans-serif" font-size="12" fill="#FFFFFF">Collections</text><text x="80" y="22" font-family="Arial, sans-serif" font-size="12" fill="#FFFFFF">Expositions</text><text x="172" y="22" font-family="Arial, sans-serif" font-size="12" font-weight="700" fill="#E1372F">Tarifs</text></g><text x="40" y="120" font-family="Georgia, serif" font-size="26" font-weight="700" fill="#0F1839">Tarifs et horaires</text><line x1="40" y1="135" x2="120" y2="135" stroke="#E1372F" stroke-width="3"/><text x="40" y="172" font-family="Arial, sans-serif" font-size="16" font-weight="700" fill="#0F1839">Billets d''entrée</text><g transform="translate(40, 190)"><rect x="0" y="0" width="280" height="80" rx="6" fill="#F4F4F4"/><text x="20" y="30" font-family="Arial, sans-serif" font-size="14" fill="#5C6573">Plein tarif</text><text x="260" y="55" text-anchor="end" font-family="Arial, sans-serif" font-size="28" font-weight="700" fill="#0F1839">12 €</text></g><g transform="translate(360, 190)"><rect x="0" y="0" width="280" height="80" rx="6" fill="#F4F4F4"/><text x="20" y="30" font-family="Arial, sans-serif" font-size="14" fill="#5C6573">Tarif réduit</text><text x="20" y="48" font-family="Arial, sans-serif" font-size="11" fill="#7A8794">(étudiants, plus de 65 ans)</text><text x="260" y="55" text-anchor="end" font-family="Arial, sans-serif" font-size="28" font-weight="700" fill="#0F1839">8 €</text></g><g transform="translate(40, 290)"><rect x="0" y="0" width="600" height="100" rx="6" fill="#E6F5EC" stroke="#168F5B" stroke-width="1.5"/><g transform="translate(20, 22)"><rect x="0" y="0" width="60" height="22" rx="11" fill="#168F5B"/><text x="30" y="15" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#FFFFFF">GRATUIT</text></g><text x="100" y="38" font-family="Arial, sans-serif" font-size="14" font-weight="600" fill="#0F1839">Pour les moins de 18 ans</text><text x="100" y="58" font-family="Arial, sans-serif" font-size="14" font-weight="600" fill="#0F1839">Pour tous, le 1er dimanche de chaque mois</text><text x="100" y="78" font-family="Arial, sans-serif" font-size="12" fill="#5C6573">Pensez à venir tôt, l''affluence est forte ces jours-là.</text></g><text x="40" y="430" font-family="Arial, sans-serif" font-size="16" font-weight="700" fill="#0F1839">Horaires d''ouverture</text><g transform="translate(40, 450)"><rect x="0" y="0" width="600" height="120" rx="6" fill="#F4F4F4"/><text x="20" y="30" font-family="Arial, sans-serif" font-size="13" fill="#5C6573">Du mardi au dimanche</text><text x="580" y="30" text-anchor="end" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#168F5B">10h — 19h</text><line x1="20" y1="45" x2="580" y2="45" stroke="#D5D5D5" stroke-width="0.5"/><text x="20" y="70" font-family="Arial, sans-serif" font-size="13" fill="#5C6573">Nocturne le mercredi</text><text x="580" y="70" text-anchor="end" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#168F5B">jusqu''à 22h</text><line x1="20" y1="85" x2="580" y2="85" stroke="#D5D5D5" stroke-width="0.5"/><text x="20" y="110" font-family="Arial, sans-serif" font-size="13" fill="#5C6573">Lundi</text><text x="580" y="110" text-anchor="end" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#E1372F">fermé</text></g></svg>');
INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0020-0000-0000-000000000001','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Annonce de colocation à Paris 11e arrondissement, 480 euros par mois charges comprises, à partir du 1er octobre, ouverte uniquement aux étudiants non-fumeurs, bail solidaire de 9 mois minimum.','2026-05-27 17:40:30.286561+02',NULL,'<svg width="100%" viewBox="0 0 680 540" role="img" xmlns="http://www.w3.org/2000/svg"><title>Petite annonce de colocation</title><desc>Annonce immobilière en ligne pour une colocation dans le 11e arrondissement de Paris, 480 euros par mois charges comprises, à partir du 1er octobre, ouverte uniquement aux étudiants non-fumeurs.</desc><rect x="0" y="0" width="680" height="540" fill="#F7F8FA"/><rect x="20" y="20" width="640" height="500" rx="8" fill="#FFFFFF" stroke="#E0E2E7" stroke-width="1"/><rect x="20" y="20" width="640" height="60" rx="8" fill="#1E3A8C"/><text x="40" y="58" font-family="Georgia, serif" font-size="22" font-weight="700" fill="#FFFFFF">ColocFacile.fr</text><text x="600" y="58" text-anchor="end" font-family="Arial, sans-serif" font-size="13" fill="#FFFFFF" opacity="0.85">Annonce mise à jour aujourd''hui</text><g transform="translate(40, 100)"><rect x="0" y="0" width="80" height="24" rx="12" fill="#168F5B"/><text x="40" y="16" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#FFFFFF">Disponible</text><rect x="92" y="0" width="120" height="24" rx="12" fill="#FDECEB"/><text x="152" y="16" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#E1372F">Étudiants uniquement</text><rect x="224" y="0" width="100" height="24" rx="12" fill="#FEF5DD"/><text x="274" y="16" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#A36E0A">Non-fumeurs</text></g><text x="40" y="170" font-family="Arial, sans-serif" font-size="22" font-weight="700" fill="#0F1839">Chambre en colocation — 16 m²</text><text x="40" y="194" font-family="Arial, sans-serif" font-size="14" fill="#5C6573">Paris 11e arrondissement · proche métro Voltaire</text><text x="40" y="244" font-family="Arial, sans-serif" font-size="32" font-weight="700" fill="#1E3A8C">480 €</text><text x="148" y="244" font-family="Arial, sans-serif" font-size="14" fill="#5C6573">/ mois</text><text x="148" y="262" font-family="Arial, sans-serif" font-size="12" font-weight="600" fill="#168F5B">charges comprises (eau, électricité, internet)</text><line x1="40" y1="284" x2="640" y2="284" stroke="#E0E2E7" stroke-width="1"/><g transform="translate(40, 305)"><text x="0" y="0" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#0F1839">Conditions d''entrée</text><text x="0" y="28" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">• Disponible à partir du <tspan font-weight="700" fill="#1E3A8C">1er octobre</tspan></text><text x="0" y="50" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">• Caution : <tspan font-weight="700">2 mois de loyer</tspan> à verser à la signature</text><text x="0" y="72" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">• Bail solidaire de <tspan font-weight="700">9 mois minimum</tspan> (année universitaire)</text><text x="0" y="94" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">• Justificatif d''études ou carte étudiant <tspan font-weight="700" fill="#E1372F">obligatoire</tspan></text></g><line x1="40" y1="415" x2="640" y2="415" stroke="#E0E2E7" stroke-width="1"/><g transform="translate(40, 435)"><text x="0" y="0" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#0F1839">À savoir</text><text x="0" y="22" font-family="Arial, sans-serif" font-size="13" fill="#5C6573">Cuisine partagée avec 3 autres colocataires. Salle de bain privée.</text><text x="0" y="42" font-family="Arial, sans-serif" font-size="13" fill="#5C6573">Animaux non acceptés. Soirées tolérées en semaine après accord.</text></g></svg>');
INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0020-0000-0000-000000000002','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Capture d''écran d''un article de presse en ligne intitulé "Télétravail : derrière la promesse, un bilan plus nuancé qu''attendu", analysant l''évolution du télétravail en France avec une position critique sur ses limites cachées.','2026-05-27 17:40:30.286561+02',NULL,'<svg width="100%" viewBox="0 0 680 820" role="img" xmlns="http://www.w3.org/2000/svg"><title>Article de presse en ligne sur le télétravail</title><desc>Capture d''écran d''un article de presse traitant de l''évolution du télétravail dans les entreprises françaises, avec une analyse nuancée des bénéfices et limites.</desc><rect x="0" y="0" width="680" height="820" fill="#F0F2F5"/><rect x="20" y="20" width="640" height="780" rx="6" fill="#FFFFFF" stroke="#D5D5D5" stroke-width="1"/><rect x="20" y="20" width="640" height="60" fill="#0F1839"/><text x="40" y="48" font-family="Georgia, serif" font-size="20" font-weight="700" fill="#FFFFFF">Le Quotidien</text><text x="40" y="66" font-family="Arial, sans-serif" font-size="10" fill="#A8B0C5">Société · Travail</text><text x="640" y="56" text-anchor="end" font-family="Arial, sans-serif" font-size="11" fill="#FFFFFF" opacity="0.8">Édition du 14 mars</text><g transform="translate(40, 100)"><rect x="0" y="0" width="90" height="22" rx="2" fill="#E1372F"/><text x="45" y="15" text-anchor="middle" font-family="Arial, sans-serif" font-size="10" font-weight="700" fill="#FFFFFF">ANALYSE</text></g><text x="40" y="158" font-family="Georgia, serif" font-size="22" font-weight="700" fill="#0F1839">Télétravail : derrière la promesse,</text><text x="40" y="186" font-family="Georgia, serif" font-size="22" font-weight="700" fill="#0F1839">un bilan plus nuancé qu''attendu</text><line x1="40" y1="208" x2="120" y2="208" stroke="#E1372F" stroke-width="3"/><text x="40" y="234" font-family="Arial, sans-serif" font-size="12" fill="#5C6573">Par Camille Verdier · 8 min de lecture</text><text x="40" y="280" font-family="Georgia, serif" font-size="14" font-style="italic" fill="#0F1839">Présenté comme une révolution durable, le télétravail s''installe</text><text x="40" y="300" font-family="Georgia, serif" font-size="14" font-style="italic" fill="#0F1839">dans le paysage professionnel français. Mais derrière l''enthousiasme</text><text x="40" y="320" font-family="Georgia, serif" font-size="14" font-style="italic" fill="#0F1839">des premiers temps, les enquêtes les plus récentes invitent à un</text><text x="40" y="340" font-family="Georgia, serif" font-size="14" font-style="italic" fill="#0F1839">examen plus lucide.</text><text x="40" y="378" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">Trois ans après sa généralisation forcée, le télétravail reste plébiscité</text><text x="40" y="396" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">par les salariés : gain de temps, meilleure conciliation vie pro / vie</text><text x="40" y="414" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">privée, autonomie renforcée. Les chiffres sont éloquents : 78 % des</text><text x="40" y="432" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">cadres déclarent ne plus vouloir y renoncer.</text><text x="40" y="466" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">Pourtant, plusieurs signaux discrets méritent d''être entendus. La</text><text x="40" y="484" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">progression des troubles musculosquelettiques chez les télétravailleurs,</text><text x="40" y="502" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">l''isolement croissant des plus jeunes en début de carrière, et surtout</text><text x="40" y="520" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">la difficulté grandissante à transmettre les savoir-faire informels</text><text x="40" y="538" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">interrogent. Les managers eux-mêmes confient peiner à évaluer la</text><text x="40" y="556" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">contribution réelle de leurs équipes.</text><text x="40" y="590" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">Plutôt que d''opposer naïvement défenseurs et détracteurs, l''heure est</text><text x="40" y="608" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">venue de penser un télétravail intelligent : limité dans son volume,</text><text x="40" y="626" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">accompagné dans ses outils, et surtout pensé en fonction des métiers et</text><text x="40" y="644" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">des moments de la carrière. Le tout-distanciel a vécu ; reste à inventer</text><text x="40" y="662" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">le bon dosage.</text><rect x="40" y="700" width="600" height="56" rx="4" fill="#F4F8FB" stroke="#D5DDE3" stroke-width="1"/><text x="56" y="722" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#5C6573">À LIRE AUSSI</text><text x="56" y="744" font-family="Arial, sans-serif" font-size="12" font-weight="600" fill="#107ACA">→ Comment les start-ups réinventent la semaine de 4 jours</text></svg>');
INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0020-0000-0000-000000000003','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Article de presse en ligne intitulé "Démissions silencieuses : un phénomène mal nommé qui en dit long", traitant du désengagement progressif des salariés au travail avec une analyse critique du terme lui-même.','2026-05-27 17:40:30.264599+02',NULL,'<svg width="100%" viewBox="0 0 680 760" role="img" xmlns="http://www.w3.org/2000/svg"><title>Article de presse sur les démissions silencieuses</title><desc>Capture d''écran d''un article de presse analysant le phénomène des démissions silencieuses.</desc><rect x="0" y="0" width="680" height="760" fill="#F0F2F5"/><rect x="20" y="20" width="640" height="720" rx="6" fill="#FFFFFF" stroke="#D5D5D5" stroke-width="1"/><rect x="20" y="20" width="640" height="60" fill="#0F1839"/><text x="40" y="48" font-family="Georgia, serif" font-size="20" font-weight="700" fill="#FFFFFF">L''Observateur</text><text x="40" y="66" font-family="Arial, sans-serif" font-size="10" fill="#A8B0C5">Économie · Travail</text><text x="640" y="56" text-anchor="end" font-family="Arial, sans-serif" font-size="11" fill="#FFFFFF" opacity="0.8">7 minutes de lecture</text><g transform="translate(40, 100)"><rect x="0" y="0" width="90" height="22" rx="2" fill="#E1372F"/><text x="45" y="15" text-anchor="middle" font-family="Arial, sans-serif" font-size="10" font-weight="700" fill="#FFFFFF">ANALYSE</text></g><text x="40" y="158" font-family="Georgia, serif" font-size="22" font-weight="700" fill="#0F1839">Démissions silencieuses :</text><text x="40" y="186" font-family="Georgia, serif" font-size="22" font-weight="700" fill="#0F1839">un phénomène mal nommé qui en dit long</text><line x1="40" y1="208" x2="120" y2="208" stroke="#E1372F" stroke-width="3"/><text x="40" y="234" font-family="Arial, sans-serif" font-size="12" fill="#5C6573">Par Lucie Bertrand · Publié hier à 18h32</text><text x="40" y="278" font-family="Georgia, serif" font-size="14" font-style="italic" fill="#0F1839">Importée des États-Unis, l''expression « démission silencieuse » désigne</text><text x="40" y="298" font-family="Georgia, serif" font-size="14" font-style="italic" fill="#0F1839">ces salariés qui restent en poste mais se contentent strictement de leurs</text><text x="40" y="318" font-family="Georgia, serif" font-size="14" font-style="italic" fill="#0F1839">missions, sans plus s''impliquer au-delà. Le terme fait recette ; il mérite</text><text x="40" y="338" font-family="Georgia, serif" font-size="14" font-style="italic" fill="#0F1839">pourtant d''être interrogé.</text><text x="40" y="378" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">D''abord, parce qu''il n''y a là rien de bien neuf. Faire ce pour quoi on est</text><text x="40" y="396" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">payé, et seulement cela, a longtemps été la règle implicite des relations</text><text x="40" y="414" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">de travail. Ce qui change, c''est moins le comportement des salariés que</text><text x="40" y="432" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">l''attente patronale d''un engagement débordant les contrats.</text><text x="40" y="466" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">Ensuite, parce que l''expression elle-même est trompeuse : on ne</text><text x="40" y="484" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">démissionne pas en restant. Ce que les enquêtes décrivent ressemble</text><text x="40" y="502" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">davantage à une forme de désengagement défensif, souvent en réaction</text><text x="40" y="520" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">à des conditions perçues comme injustes : management vertical, salaires</text><text x="40" y="538" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">stagnants, demandes opérationnelles croissantes.</text><text x="40" y="572" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">Plutôt que de stigmatiser ces salariés en quête de juste contrepartie,</text><text x="40" y="590" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">les organisations gagneraient à entendre ce qu''ils disent par leur</text><text x="40" y="608" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">retrait : non pas un refus du travail, mais le refus d''un déséquilibre</text><text x="40" y="626" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">durable entre ce qui est donné et ce qui est reconnu.</text><rect x="40" y="660" width="600" height="50" rx="4" fill="#F4F8FB" stroke="#D5DDE3" stroke-width="1"/><text x="56" y="680" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#5C6573">DANS LA MÊME RUBRIQUE</text><text x="56" y="700" font-family="Arial, sans-serif" font-size="12" font-weight="600" fill="#107ACA">→ La grande démission a-t-elle vraiment eu lieu en France ?</text></svg>');
INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0020-0000-0000-000000000004','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Tribune d''opinion en ligne signée par une artiste, intitulée "L''intelligence artificielle ne remplacera pas la créativité, mais elle changera ce qu''on appelle ainsi", proposant une réflexion nuancée sur les outils génératifs.','2026-05-27 17:40:30.264599+02',NULL,'<svg width="100%" viewBox="0 0 680 760" role="img" xmlns="http://www.w3.org/2000/svg"><title>Tribune d''opinion sur l''IA et la créativité</title><desc>Capture d''écran d''une tribune signée par une artiste sur l''impact de l''IA générative.</desc><rect x="0" y="0" width="680" height="760" fill="#F8F6F0"/><rect x="20" y="20" width="640" height="720" rx="6" fill="#FFFEF9" stroke="#D5D5C8" stroke-width="1"/><rect x="20" y="20" width="640" height="50" fill="#1E3A8C"/><text x="40" y="50" font-family="Georgia, serif" font-size="20" font-weight="700" font-style="italic" fill="#FFFFFF">La Tribune Libre</text><text x="640" y="48" text-anchor="end" font-family="Arial, sans-serif" font-size="10" fill="#FFFFFF" opacity="0.8">Opinions · Idées</text><g transform="translate(40, 90)"><rect x="0" y="0" width="100" height="22" rx="2" fill="#1E3A8C"/><text x="50" y="15" text-anchor="middle" font-family="Arial, sans-serif" font-size="10" font-weight="700" fill="#FFFFFF">TRIBUNE</text></g><text x="40" y="148" font-family="Georgia, serif" font-size="20" font-weight="700" fill="#0F1839">« L''intelligence artificielle ne</text><text x="40" y="172" font-family="Georgia, serif" font-size="20" font-weight="700" fill="#0F1839">remplacera pas la créativité, mais</text><text x="40" y="196" font-family="Georgia, serif" font-size="20" font-weight="700" fill="#0F1839">elle changera ce qu''on appelle ainsi »</text><line x1="40" y1="216" x2="180" y2="216" stroke="#1E3A8C" stroke-width="2"/><text x="40" y="244" font-family="Arial, sans-serif" font-size="12" font-style="italic" fill="#5C6573">Par Hélène Marchand, artiste plasticienne</text><text x="40" y="282" font-family="Georgia, serif" font-size="13" fill="#0F1839">Les outils génératifs nous mettent face à un trouble singulier. Avec eux,</text><text x="40" y="300" font-family="Georgia, serif" font-size="13" fill="#0F1839">la production d''images, de musiques, de textes devient un geste presque</text><text x="40" y="318" font-family="Georgia, serif" font-size="13" fill="#0F1839">trivial. Ce qui demandait une vie d''apprentissage tient désormais dans</text><text x="40" y="336" font-family="Georgia, serif" font-size="13" fill="#0F1839">quelques lignes de texte. Pour beaucoup d''artistes, ce constat brutal</text><text x="40" y="354" font-family="Georgia, serif" font-size="13" fill="#0F1839">est vécu comme une menace existentielle. Je ne le crois pas.</text><text x="40" y="388" font-family="Georgia, serif" font-size="13" fill="#0F1839">Ce que ces outils déplacent, ce n''est pas la capacité à créer, mais ce</text><text x="40" y="406" font-family="Georgia, serif" font-size="13" fill="#0F1839">qu''on choisit d''appeler de la création. Pendant longtemps, le savoir-</text><text x="40" y="424" font-family="Georgia, serif" font-size="13" fill="#0F1839">faire technique a fait office de critère. Avec l''IA, la prouesse technique</text><text x="40" y="442" font-family="Georgia, serif" font-size="13" fill="#0F1839">se banalise. Reste l''intention : le pourquoi, le sens, le regard.</text><text x="40" y="476" font-family="Georgia, serif" font-size="13" fill="#0F1839">Loin de tuer l''art, l''IA pourrait paradoxalement le purifier en le forçant</text><text x="40" y="494" font-family="Georgia, serif" font-size="13" fill="#0F1839">à se redéfinir autour de ce qu''aucune machine ne peut imiter : l''intuition</text><text x="40" y="512" font-family="Georgia, serif" font-size="13" fill="#0F1839">d''un vécu, la décision de montrer ceci plutôt que cela, la singularité</text><text x="40" y="530" font-family="Georgia, serif" font-size="13" fill="#0F1839">d''un parcours.</text><text x="40" y="564" font-family="Georgia, serif" font-size="13" fill="#0F1839">La vraie question n''est donc pas « l''IA va-t-elle remplacer les artistes »,</text><text x="40" y="582" font-family="Georgia, serif" font-size="13" fill="#0F1839">mais « que valait notre définition de l''art si une machine peut désormais</text><text x="40" y="600" font-family="Georgia, serif" font-size="13" fill="#0F1839">en produire les apparences ? » Voilà, à mes yeux, le seul débat sérieux.</text><line x1="40" y1="640" x2="640" y2="640" stroke="#D5D5C8" stroke-width="0.5"/><text x="40" y="670" font-family="Arial, sans-serif" font-size="11" font-style="italic" fill="#5C6573">Hélène Marchand expose actuellement à la galerie du Marais.</text></svg>');
INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0020-0000-0000-000000000005','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Lettre administrative d''un bailleur notifiant une révision annuelle de loyer en application de l''indice de référence, avec mention des voies de contestation et d''un complément exceptionnel pour travaux.','2026-05-27 17:40:30.264599+02',NULL,'<svg width="100%" viewBox="0 0 680 880" role="img" xmlns="http://www.w3.org/2000/svg"><title>Lettre de révision de loyer</title><desc>Lettre administrative d''un bailleur notifiant à un locataire la révision annuelle de loyer et un complément pour travaux.</desc><rect x="0" y="0" width="680" height="880" fill="#F5F5F5"/><rect x="40" y="40" width="600" height="800" fill="#FFFFFF" stroke="#D5D5D5" stroke-width="1"/><g transform="translate(60, 60)"><text x="0" y="0" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#0F1839">SCI Les Tilleuls</text><text x="0" y="18" font-family="Arial, sans-serif" font-size="11" fill="#5C6573">14 rue Lafayette, 75009 Paris</text><text x="0" y="34" font-family="Arial, sans-serif" font-size="11" fill="#5C6573">contact@les-tilleuls.fr</text></g><g transform="translate(360, 60)"><text x="0" y="0" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">Mme Sarah LEROUX</text><text x="0" y="16" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">22 rue des Acacias</text><text x="0" y="32" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">75011 Paris</text></g><text x="60" y="180" font-family="Arial, sans-serif" font-size="11" fill="#5C6573">Paris, le 14 mars</text><text x="60" y="215" font-family="Arial, sans-serif" font-size="12" font-weight="700" fill="#0F1839">Objet : Révision annuelle du loyer — bail signé le 1er avril 2022</text><text x="60" y="231" font-family="Arial, sans-serif" font-size="11" fill="#5C6573">Lettre recommandée avec accusé de réception</text><text x="60" y="278" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">Madame Leroux,</text><text x="60" y="312" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">Conformément aux dispositions de votre bail et à la loi du 6 juillet 1989,</text><text x="60" y="330" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">nous procédons à la révision annuelle de votre loyer, sur la base de</text><text x="60" y="348" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">l''indice de référence des loyers (IRL) publié par l''INSEE.</text><rect x="60" y="370" width="540" height="100" rx="4" fill="#F4F8FB" stroke="#D5DDE3" stroke-width="1"/><text x="76" y="392" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#5C6573">DÉTAIL DE LA RÉVISION</text><text x="76" y="416" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">Ancien loyer hors charges :</text><text x="540" y="416" text-anchor="end" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">820,00 €</text><text x="76" y="436" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">Variation IRL appliquée (+3,5%) :</text><text x="540" y="436" text-anchor="end" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">+28,70 €</text><text x="76" y="458" font-family="Arial, sans-serif" font-size="12" font-weight="700" fill="#0F1839">Nouveau loyer hors charges :</text><text x="540" y="458" text-anchor="end" font-family="Arial, sans-serif" font-size="12" font-weight="700" fill="#1E3A8C">848,70 €</text><text x="60" y="498" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">Cette révision prendra effet à compter du <tspan font-weight="700">1er avril prochain</tspan>.</text><text x="60" y="532" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">Par ailleurs, nous souhaitons vous informer qu''un complément temporaire de</text><text x="60" y="550" font-family="Arial, sans-serif" font-size="12" fill="#0F1839"><tspan font-weight="700">15 € par mois pendant 12 mois</tspan> sera appliqué pour financer la réfection</text><text x="60" y="568" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">de la toiture de l''immeuble. Ce complément, prévu par l''article 17-1 de</text><text x="60" y="586" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">la loi, cesse automatiquement à l''issue de cette période.</text><rect x="60" y="608" width="540" height="58" rx="4" fill="#FDECEB" stroke="#E1372F" stroke-width="1"/><text x="76" y="628" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#E1372F">VOIE DE CONTESTATION</text><text x="76" y="646" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">Si vous estimez cette révision irrégulière, vous disposez d''un délai de</text><text x="76" y="660" font-family="Arial, sans-serif" font-size="11" fill="#0F1839"><tspan font-weight="700">deux mois</tspan> pour saisir la commission départementale de conciliation.</text><text x="60" y="700" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">Nous restons à votre disposition pour toute précision.</text><text x="60" y="730" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">Cordialement,</text><text x="60" y="770" font-family="Georgia, serif" font-size="14" font-style="italic" fill="#1E3A8C">Jean-Marc Vidal</text><text x="60" y="788" font-family="Arial, sans-serif" font-size="11" fill="#5C6573">Gérant — SCI Les Tilleuls</text></svg>');
INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0020-0000-0000-000000000006','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Extrait d''un rapport d''observatoire sur le bien-être au travail, présentant des chiffres et conclusions sur le décalage entre les actions des entreprises et les attentes réelles des salariés.','2026-05-27 17:40:30.264599+02',NULL,'<svg width="100%" viewBox="0 0 680 800" role="img" xmlns="http://www.w3.org/2000/svg"><title>Extrait de rapport sur le bien-être au travail</title><desc>Capture d''un extrait de rapport d''observatoire avec chiffres clés et synthèse.</desc><rect x="0" y="0" width="680" height="800" fill="#F2F5F8"/><rect x="20" y="20" width="640" height="760" fill="#FFFFFF" stroke="#C8D0D8" stroke-width="1"/><rect x="20" y="20" width="640" height="80" fill="#15296B"/><text x="40" y="50" font-family="Georgia, serif" font-size="14" fill="#A8B0C5">OBSERVATOIRE DU TRAVAIL — ÉDITION 2026</text><text x="40" y="80" font-family="Georgia, serif" font-size="20" font-weight="700" fill="#FFFFFF">Bien-être au travail : ce que disent vraiment les salariés</text><g transform="translate(40, 130)"><rect x="0" y="0" width="100" height="22" rx="2" fill="#168F5B"/><text x="50" y="15" text-anchor="middle" font-family="Arial, sans-serif" font-size="10" font-weight="700" fill="#FFFFFF">SYNTHÈSE</text></g><text x="40" y="190" font-family="Georgia, serif" font-size="18" font-weight="700" fill="#0F1839">Un décalage croissant entre les actions menées</text><text x="40" y="214" font-family="Georgia, serif" font-size="18" font-weight="700" fill="#0F1839">et les attentes réelles des collaborateurs</text><line x1="40" y1="232" x2="160" y2="232" stroke="#168F5B" stroke-width="3"/><g transform="translate(40, 270)"><rect x="0" y="0" width="285" height="100" rx="6" fill="#E8F5EE" stroke="#168F5B" stroke-width="0.5"/><text x="20" y="32" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#168F5B">CHIFFRE CLÉ</text><text x="20" y="62" font-family="Georgia, serif" font-size="28" font-weight="700" fill="#168F5B">73%</text><text x="20" y="85" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">des salariés jugent les baby-foot</text><text x="20" y="100" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">et tables de ping-pong inutiles</text></g><g transform="translate(355, 270)"><rect x="0" y="0" width="285" height="100" rx="6" fill="#FDECEB" stroke="#E1372F" stroke-width="0.5"/><text x="20" y="32" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#E1372F">CHIFFRE CLÉ</text><text x="20" y="62" font-family="Georgia, serif" font-size="28" font-weight="700" fill="#E1372F">2 sur 3</text><text x="20" y="85" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">attendent une revalorisation</text><text x="20" y="100" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">salariale avant tout</text></g><text x="40" y="412" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">Les conclusions de cette septième édition de l''observatoire sont sans</text><text x="40" y="430" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">appel : les politiques de bien-être au travail, telles qu''elles sont</text><text x="40" y="448" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">pensées par la plupart des grandes entreprises, manquent largement leur</text><text x="40" y="466" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">cible. Les dispositifs les plus visibles — espaces de détente, événements</text><text x="40" y="484" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">internes, séminaires « bonheur » — peinent à convaincre.</text><text x="40" y="518" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">À l''inverse, les attentes des salariés se cristallisent autour de trois</text><text x="40" y="536" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">axes fondamentaux : la rémunération, le respect du temps de vie</text><text x="40" y="554" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">personnelle, et la reconnaissance par le management direct du travail</text><text x="40" y="572" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">accompli.</text><text x="40" y="606" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">Le rapport recommande aux directions de renoncer aux dispositifs</text><text x="40" y="624" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">cosmétiques et de réinvestir prioritairement dans ce qui structure</text><text x="40" y="642" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">durablement la qualité de vie au travail.</text><rect x="40" y="680" width="600" height="60" rx="4" fill="#F4F8FB" stroke="#D5DDE3" stroke-width="1"/><text x="56" y="704" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#5C6573">MÉTHODOLOGIE</text><text x="56" y="724" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">Enquête menée auprès de 4 200 salariés du secteur privé, de janvier à</text><text x="56" y="738" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">novembre. Échantillon représentatif redressé selon l''âge, le secteur et la taille.</text></svg>');
INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0020-0000-0000-000000000007','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Article de blog éditorial intitulé "Le slow tourisme, mode passagère ou vraie transition ?", interrogeant la sincérité d''une tendance touristique qui se revendique éthique.','2026-05-27 17:40:30.264599+02',NULL,'<svg width="100%" viewBox="0 0 680 760" role="img" xmlns="http://www.w3.org/2000/svg"><title>Article de blog sur le slow tourisme</title><desc>Capture d''un blog éditorial sur la tendance du slow tourisme.</desc><rect x="0" y="0" width="680" height="760" fill="#FBF8F2"/><rect x="20" y="20" width="640" height="720" rx="8" fill="#FFFFFF" stroke="#E8E0CC" stroke-width="1"/><rect x="20" y="20" width="640" height="50" fill="#168F5B"/><text x="40" y="50" font-family="Georgia, serif" font-size="18" font-weight="700" fill="#FFFFFF">Voyages &amp; Réflexions</text><text x="640" y="48" text-anchor="end" font-family="Arial, sans-serif" font-size="10" fill="#FFFFFF" opacity="0.8">Le blog · 3 commentaires</text><g transform="translate(40, 90)"><rect x="0" y="0" width="120" height="22" rx="11" fill="#E8F5EE"/><text x="60" y="15" text-anchor="middle" font-family="Arial, sans-serif" font-size="10" font-weight="700" fill="#168F5B">Tendances</text></g><text x="40" y="148" font-family="Georgia, serif" font-size="22" font-weight="700" fill="#0F1839">Le slow tourisme :</text><text x="40" y="178" font-family="Georgia, serif" font-size="22" font-weight="700" fill="#0F1839">mode passagère ou vraie transition ?</text><line x1="40" y1="200" x2="120" y2="200" stroke="#168F5B" stroke-width="3"/><text x="40" y="228" font-family="Arial, sans-serif" font-size="12" fill="#5C6573">Sophie Aubry · Vendredi · Lecture : 6 min</text><text x="40" y="276" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">Voyager moins, mais mieux. Privilégier le train, séjourner plus longtemps,</text><text x="40" y="294" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">consommer local. Le « slow tourisme » s''affiche désormais partout :</text><text x="40" y="312" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">brochures d''offices de tourisme, guides de voyage, plateformes de</text><text x="40" y="330" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">réservation. Le succès du label est incontestable. Sa portée réelle, en</text><text x="40" y="348" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">revanche, mérite qu''on s''y attarde.</text><text x="40" y="382" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">Sur le papier, l''engagement écologique est sérieux. Dans les faits,</text><text x="40" y="400" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">plusieurs études récentes nuancent le tableau : pour beaucoup de voyageurs,</text><text x="40" y="418" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">le slow tourisme s''ajoute à des voyages longue distance, sans s''y</text><text x="40" y="436" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">substituer. On part en train à 200 km de chez soi pour un week-end</text><text x="40" y="454" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">« responsable », puis on prend l''avion six mois plus tard pour les vraies</text><text x="40" y="472" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">vacances. Le bilan carbone, lui, ne distingue pas la bonne conscience.</text><text x="40" y="506" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">Faut-il pour autant disqualifier la démarche ? Certainement pas. Mais il</text><text x="40" y="524" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">faut sortir d''une lecture cosmétique. Un slow tourisme sincère suppose un</text><text x="40" y="542" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">arbitrage : moins de déplacements lointains, pas l''ajout d''escapades</text><text x="40" y="560" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">vertueuses entre deux long-courriers.</text><text x="40" y="594" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">La transition écologique du tourisme passera par cette honnêteté. Sinon,</text><text x="40" y="612" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">la formule restera un argument marketing rassurant, et rien de plus.</text><line x1="40" y1="650" x2="640" y2="650" stroke="#E8E0CC" stroke-width="0.5"/><g transform="translate(40, 680)"><rect x="0" y="0" width="100" height="20" rx="2" fill="#F5F0E0"/><text x="50" y="14" text-anchor="middle" font-family="Arial, sans-serif" font-size="10" fill="#A36E0A">slow tourisme</text></g><g transform="translate(150, 680)"><rect x="0" y="0" width="80" height="20" rx="2" fill="#F5F0E0"/><text x="40" y="14" text-anchor="middle" font-family="Arial, sans-serif" font-size="10" fill="#A36E0A">écologie</text></g></svg>');
INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0020-0000-0000-000000000008','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Page web d''un organisme de formation continue présentant une formation diplômante en management, avec conditions d''accès strictes (dont expérience professionnelle minimum), tarif et modalités de financement.','2026-05-27 17:40:30.264599+02',NULL,'<svg width="100%" viewBox="0 0 680 740" role="img" xmlns="http://www.w3.org/2000/svg"><title>Page web d''une formation continue en management</title><desc>Capture du site d''un organisme de formation : programme diplômant, conditions d''accès, prix, financement.</desc><rect x="0" y="0" width="680" height="740" fill="#F4F7FB"/><rect x="20" y="20" width="640" height="700" rx="8" fill="#FFFFFF" stroke="#D5DDE3" stroke-width="1"/><rect x="20" y="20" width="640" height="60" rx="8" fill="#1E3A8C"/><text x="40" y="58" font-family="Georgia, serif" font-size="20" font-weight="700" fill="#FFFFFF">FormaPro</text><text x="115" y="58" font-family="Arial, sans-serif" font-size="11" fill="#A8B0C5">— École de management</text><text x="600" y="50" text-anchor="end" font-family="Arial, sans-serif" font-size="11" fill="#FFFFFF">Catalogue 2026</text><text x="600" y="65" text-anchor="end" font-family="Arial, sans-serif" font-size="10" fill="#A8B0C5">Mis à jour</text><g transform="translate(40, 100)"><rect x="0" y="0" width="80" height="22" rx="11" fill="#168F5B"/><text x="40" y="15" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#FFFFFF">Diplômant</text><rect x="92" y="0" width="100" height="22" rx="11" fill="#FEF5DD"/><text x="142" y="15" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#A36E0A">Bac+5 reconnu</text><rect x="204" y="0" width="100" height="22" rx="11" fill="#E8ECF8"/><text x="254" y="15" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#1E3A8C">Niveau 7 RNCP</text></g><text x="40" y="170" font-family="Arial, sans-serif" font-size="22" font-weight="700" fill="#0F1839">Master Management des Organisations</text><text x="40" y="195" font-family="Arial, sans-serif" font-size="14" fill="#5C6573">Formation continue pour cadres en activité — Rentrée septembre</text><text x="40" y="246" font-family="Arial, sans-serif" font-size="32" font-weight="700" fill="#1E3A8C">9 800 €</text><text x="180" y="246" font-family="Arial, sans-serif" font-size="14" fill="#5C6573">au total</text><text x="180" y="264" font-family="Arial, sans-serif" font-size="12" font-weight="600" fill="#168F5B">éligible CPF + financement employeur possible</text><line x1="40" y1="284" x2="640" y2="284" stroke="#E0E2E7" stroke-width="1"/><text x="40" y="316" font-family="Arial, sans-serif" font-size="15" font-weight="700" fill="#0F1839">Conditions d''accès</text><g transform="translate(40, 340)"><circle cx="6" cy="6" r="3" fill="#1E3A8C"/><text x="20" y="10" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">Diplôme de niveau Bac+3 minimum (ou équivalent VAE)</text></g><g transform="translate(40, 370)"><circle cx="6" cy="6" r="3" fill="#1E3A8C"/><text x="20" y="10" font-family="Arial, sans-serif" font-size="13" fill="#0F1839"><tspan font-weight="700">Au moins 5 ans d''expérience professionnelle</tspan> dont 2 en encadrement</text></g><g transform="translate(40, 400)"><circle cx="6" cy="6" r="3" fill="#1E3A8C"/><text x="20" y="10" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">Sélection sur dossier <tspan font-weight="700">+ entretien individuel obligatoire</tspan></text></g><g transform="translate(40, 430)"><circle cx="6" cy="6" r="3" fill="#1E3A8C"/><text x="20" y="10" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">Lettre de motivation de l''employeur (si financement entreprise)</text></g><line x1="40" y1="470" x2="640" y2="470" stroke="#E0E2E7" stroke-width="1"/><text x="40" y="502" font-family="Arial, sans-serif" font-size="15" font-weight="700" fill="#0F1839">Modalités</text><text x="40" y="528" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">• Rythme : <tspan font-weight="700">2 jours par mois sur 18 mois</tspan> (jeudi/vendredi)</text><text x="40" y="548" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">• Hybride : présentiel à Paris + sessions à distance</text><text x="40" y="568" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">• Promotion limitée à 24 participants pour favoriser les échanges</text><rect x="40" y="600" width="600" height="80" rx="6" fill="#FDECEB" stroke="#E1372F" stroke-width="1"/><text x="56" y="624" font-family="Arial, sans-serif" font-size="12" font-weight="700" fill="#E1372F">⚠ INSCRIPTIONS</text><text x="56" y="646" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">Date limite de dépôt des dossiers : <tspan font-weight="700">15 juin</tspan>. Résultats fin juillet.</text><text x="56" y="664" font-family="Arial, sans-serif" font-size="11" fill="#5C6573">Aucun dossier ne sera accepté après cette date, y compris pour les financements CPF.</text></svg>');
INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0021-0000-0000-000000000001','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'E-mail professionnel d''un manager annonçant à son équipe le report d''une réunion initialement prévue le mardi à 10h, désormais reportée au jeudi à 14h en salle B, avec un changement d''ordre du jour.','2026-05-27 17:40:30.246972+02',NULL,'<svg width="100%" viewBox="0 0 680 580" role="img" xmlns="http://www.w3.org/2000/svg"><title>E-mail professionnel : report de réunion</title><desc>E-mail d''un manager à son équipe pour reporter une réunion et modifier l''ordre du jour.</desc><rect x="0" y="0" width="680" height="580" fill="#F1F3F4"/><rect x="20" y="20" width="640" height="540" rx="8" fill="#FFFFFF" stroke="#DADCE0" stroke-width="1"/><rect x="20" y="20" width="640" height="50" fill="#FFFFFF"/><line x1="20" y1="70" x2="660" y2="70" stroke="#DADCE0" stroke-width="0.5"/><g transform="translate(40, 32)"><rect x="0" y="4" width="20" height="2" fill="#5F6368" rx="1"/><rect x="0" y="11" width="20" height="2" fill="#5F6368" rx="1"/><rect x="0" y="18" width="20" height="2" fill="#5F6368" rx="1"/></g><text x="80" y="50" font-family="Arial, sans-serif" font-size="18" font-weight="500" fill="#5F6368">Boîte de réception</text><g transform="translate(580, 30)"><rect x="0" y="0" width="32" height="32" rx="16" fill="#1A73E8"/><text x="16" y="22" text-anchor="middle" font-family="Arial, sans-serif" font-size="14" font-weight="600" fill="#FFFFFF">T</text></g><rect x="40" y="100" width="600" height="440" fill="#FFFFFF"/><text x="40" y="128" font-family="Arial, sans-serif" font-size="17" font-weight="600" fill="#202124">Report de la réunion d''équipe — modification d''horaire</text><g transform="translate(40, 152)"><circle cx="20" cy="20" r="20" fill="#34A853"/><text x="20" y="26" text-anchor="middle" font-family="Arial, sans-serif" font-size="16" font-weight="600" fill="#FFFFFF">T</text></g><text x="92" y="164" font-family="Arial, sans-serif" font-size="13" font-weight="600" fill="#202124">Thomas Berger</text><text x="190" y="164" font-family="Arial, sans-serif" font-size="12" fill="#5F6368">&lt;thomas.b@entreprise.fr&gt;</text><text x="92" y="183" font-family="Arial, sans-serif" font-size="12" fill="#5F6368">à équipe-projet</text><text x="600" y="164" text-anchor="end" font-family="Arial, sans-serif" font-size="11" fill="#5F6368">Aujourd''hui 09:14</text><line x1="40" y1="210" x2="640" y2="210" stroke="#DADCE0" stroke-width="0.5"/><text x="40" y="244" font-family="Arial, sans-serif" font-size="13" fill="#202124">Bonjour à tous,</text><text x="40" y="276" font-family="Arial, sans-serif" font-size="13" fill="#202124">Petit changement de programme : <tspan font-weight="700">la réunion d''équipe initialement prévue</tspan></text><text x="40" y="294" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#202124">mardi à 10h est reportée à jeudi 14h en salle B</text><text x="350" y="294" font-family="Arial, sans-serif" font-size="13" fill="#202124"> (et non plus en salle A).</text><text x="40" y="328" font-family="Arial, sans-serif" font-size="13" fill="#202124">Nous y aborderons les points suivants :</text><text x="60" y="354" font-family="Arial, sans-serif" font-size="13" fill="#202124">• Bilan du trimestre (Camille)</text><text x="60" y="376" font-family="Arial, sans-serif" font-size="13" fill="#202124">• Présentation du nouveau client (Marc)</text><text x="60" y="398" font-family="Arial, sans-serif" font-size="13" fill="#202124">• Recrutement en cours (moi-même)</text><text x="40" y="430" font-family="Arial, sans-serif" font-size="13" fill="#202124">Le point sur le budget annuel, que nous devions traiter mardi, est <tspan font-weight="700">décalé</tspan></text><text x="40" y="448" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#202124">à la prochaine réunion de la semaine suivante</text><text x="380" y="448" font-family="Arial, sans-serif" font-size="13" fill="#202124">, faute de temps.</text><text x="40" y="482" font-family="Arial, sans-serif" font-size="13" fill="#202124">Merci de confirmer votre présence avant mercredi midi.</text><text x="40" y="514" font-family="Arial, sans-serif" font-size="13" fill="#202124">Bonne journée,</text><text x="40" y="532" font-family="Arial, sans-serif" font-size="13" fill="#202124">Thomas</text></svg>');
INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0021-0000-0000-000000000002','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Affiche annonçant un atelier cuisine "Pâtisserie d''automne" le samedi 12 octobre à 14h, 35 euros par personne, places limitées à 8 participants, sur inscription préalable. Niveau débutant accepté, matériel et tablier fournis.','2026-05-27 17:40:30.246972+02',NULL,'<svg width="100%" viewBox="0 0 680 800" role="img" xmlns="http://www.w3.org/2000/svg"><title>Affiche atelier cuisine pâtisserie d''automne</title><desc>Affiche d''un atelier cuisine de pâtisserie le samedi 12 octobre à 14h, 35 euros, 8 places maximum.</desc><rect x="0" y="0" width="680" height="800" fill="#FAEEDA"/><rect x="40" y="40" width="600" height="720" fill="#FFFFFF" stroke="#854F0B" stroke-width="3"/><rect x="60" y="60" width="560" height="80" fill="#854F0B"/><text x="340" y="100" text-anchor="middle" font-family="Georgia, serif" font-size="28" font-weight="700" fill="#FFFFFF">L''ATELIER DU GOÛT</text><text x="340" y="125" text-anchor="middle" font-family="Georgia, serif" font-size="13" font-style="italic" fill="#FAEEDA">cours de cuisine en petit comité</text><text x="340" y="200" text-anchor="middle" font-family="Arial, sans-serif" font-size="15" font-weight="600" fill="#854F0B">PROCHAIN ATELIER</text><line x1="280" y1="212" x2="400" y2="212" stroke="#E1372F" stroke-width="2"/><text x="340" y="250" text-anchor="middle" font-family="Georgia, serif" font-size="32" font-weight="700" fill="#0F1839">Pâtisserie d''automne</text><text x="340" y="280" text-anchor="middle" font-family="Georgia, serif" font-size="15" font-style="italic" fill="#5C6573">tarte aux pommes, crumble &amp; financiers</text><g transform="translate(140, 320)"><rect x="0" y="0" width="180" height="80" rx="8" fill="#FFF8E8" stroke="#854F0B" stroke-width="1"/><text x="90" y="24" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#854F0B">QUAND</text><text x="90" y="48" text-anchor="middle" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#0F1839">Samedi 12 octobre</text><text x="90" y="68" text-anchor="middle" font-family="Arial, sans-serif" font-size="18" font-weight="700" fill="#E1372F">14h — 17h</text></g><g transform="translate(360, 320)"><rect x="0" y="0" width="180" height="80" rx="8" fill="#FFF8E8" stroke="#854F0B" stroke-width="1"/><text x="90" y="24" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#854F0B">TARIF</text><text x="90" y="56" text-anchor="middle" font-family="Arial, sans-serif" font-size="28" font-weight="700" fill="#E1372F">35 €</text><text x="90" y="72" text-anchor="middle" font-family="Arial, sans-serif" font-size="10" fill="#5C6573">par personne, tout inclus</text></g><line x1="120" y1="430" x2="560" y2="430" stroke="#854F0B" stroke-width="1" stroke-dasharray="4 4"/><g transform="translate(120, 460)"><circle cx="6" cy="8" r="3" fill="#168F5B"/><text x="20" y="12" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">Tous niveaux acceptés, débutants bienvenus</text></g><g transform="translate(120, 488)"><circle cx="6" cy="8" r="3" fill="#168F5B"/><text x="20" y="12" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">Matériel et tablier fournis sur place</text></g><g transform="translate(120, 516)"><circle cx="6" cy="8" r="3" fill="#168F5B"/><text x="20" y="12" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">Vous repartez avec vos préparations</text></g><g transform="translate(120, 544)"><circle cx="6" cy="8" r="3" fill="#E1372F"/><text x="20" y="12" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#E1372F">8 places maximum — inscription préalable obligatoire</text></g><rect x="120" y="600" width="440" height="80" rx="6" fill="#854F0B"/><text x="340" y="624" text-anchor="middle" font-family="Arial, sans-serif" font-size="12" font-weight="700" fill="#FAEEDA">RÉSERVATION</text><text x="340" y="648" text-anchor="middle" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#FFFFFF">par téléphone au 05 56 12 34 56</text><text x="340" y="668" text-anchor="middle" font-family="Arial, sans-serif" font-size="12" fill="#FAEEDA">ou par mail : contact@latelier-du-gout.fr</text><text x="340" y="720" text-anchor="middle" font-family="Georgia, serif" font-size="11" font-style="italic" fill="#854F0B">12 rue des Tilleuls — 33000 Bordeaux</text></svg>');
INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0021-0000-0000-000000000003','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Capture d''écran d''une application de livraison de repas affichant le récapitulatif d''une commande : 2 plats, sous-total 24 euros, code promo nouveau-client appliqué (-5 euros), frais de livraison 2,50 euros, total 21,50 euros, livraison estimée dans 35-45 minutes.','2026-05-27 17:40:30.246972+02',NULL,'<svg width="100%" viewBox="0 0 680 760" role="img" xmlns="http://www.w3.org/2000/svg"><title>Application de livraison — récapitulatif de commande</title><desc>Capture d''écran d''une application de livraison de repas avec détail prix et code promo.</desc><rect x="0" y="0" width="680" height="760" fill="#F5F5F7"/><rect x="170" y="40" width="340" height="700" rx="32" fill="#1A1A1A"/><rect x="180" y="80" width="320" height="660" rx="4" fill="#FFFFFF"/><rect x="280" y="50" width="120" height="22" rx="11" fill="#1A1A1A"/><text x="200" y="104" font-family="Arial, sans-serif" font-size="13" font-weight="600" fill="#0F1839">9:42</text><g transform="translate(440, 92)"><rect x="0" y="0" width="3" height="8" rx="0.5" fill="#0F1839"/><rect x="5" y="-2" width="3" height="10" rx="0.5" fill="#0F1839"/><rect x="10" y="-4" width="3" height="12" rx="0.5" fill="#0F1839"/><rect x="15" y="-6" width="3" height="14" rx="0.5" fill="#0F1839"/></g><rect x="180" y="120" width="320" height="50" fill="#FF6B35"/><text x="340" y="150" text-anchor="middle" font-family="Arial, sans-serif" font-size="16" font-weight="700" fill="#FFFFFF">Récapitulatif</text><g transform="translate(200, 135)"><path d="M 6 0 L 0 8 L 6 16" fill="none" stroke="#FFFFFF" stroke-width="2" stroke-linecap="round"/></g><rect x="200" y="190" width="280" height="100" rx="8" fill="#FAFAFA" stroke="#E5E5E7" stroke-width="0.5"/><text x="216" y="216" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#0F1839">Le Petit Bistrot</text><text x="216" y="234" font-family="Arial, sans-serif" font-size="11" fill="#5F6368">⭐ 4,7 · Cuisine française · 1,2 km</text><line x1="216" y1="248" x2="464" y2="248" stroke="#E5E5E7" stroke-width="0.5"/><text x="216" y="268" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">Tagliatelles aux champignons</text><text x="464" y="268" text-anchor="end" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">12,00 €</text><text x="216" y="284" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">Steak frites maison</text><text x="464" y="284" text-anchor="end" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">12,00 €</text><rect x="200" y="310" width="280" height="160" rx="8" fill="#FAFAFA" stroke="#E5E5E7" stroke-width="0.5"/><text x="216" y="336" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#0F1839">Détail du paiement</text><text x="216" y="362" font-family="Arial, sans-serif" font-size="12" fill="#5F6368">Sous-total (2 plats)</text><text x="464" y="362" text-anchor="end" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">24,00 €</text><text x="216" y="384" font-family="Arial, sans-serif" font-size="12" fill="#168F5B">Code BIENVENUE (nouveau client)</text><text x="464" y="384" text-anchor="end" font-family="Arial, sans-serif" font-size="12" font-weight="700" fill="#168F5B">−5,00 €</text><text x="216" y="406" font-family="Arial, sans-serif" font-size="12" fill="#5F6368">Frais de livraison</text><text x="464" y="406" text-anchor="end" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">+2,50 €</text><line x1="216" y1="420" x2="464" y2="420" stroke="#E5E5E7" stroke-width="0.5"/><text x="216" y="446" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#0F1839">Total à payer</text><text x="464" y="446" text-anchor="end" font-family="Arial, sans-serif" font-size="17" font-weight="700" fill="#FF6B35">21,50 €</text><rect x="200" y="490" width="280" height="90" rx="8" fill="#FFF6F0" stroke="#FF6B35" stroke-width="1"/><text x="216" y="514" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#FF6B35">🛵 LIVRAISON ESTIMÉE</text><text x="216" y="538" font-family="Arial, sans-serif" font-size="18" font-weight="700" fill="#0F1839">35 — 45 minutes</text><text x="216" y="558" font-family="Arial, sans-serif" font-size="11" fill="#5F6368">soit entre 10h17 et 10h27</text><text x="216" y="572" font-family="Arial, sans-serif" font-size="10" font-style="italic" fill="#5F6368">Délais variables selon la circulation</text><rect x="200" y="600" width="280" height="48" rx="24" fill="#FF6B35"/><text x="340" y="630" text-anchor="middle" font-family="Arial, sans-serif" font-size="15" font-weight="700" fill="#FFFFFF">Confirmer et payer 21,50 €</text><text x="340" y="680" text-anchor="middle" font-family="Arial, sans-serif" font-size="10" fill="#5F6368">Code promo non cumulable avec d''autres offres</text></svg>');
INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0021-0000-0000-000000000004','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Annonce de vente entre particuliers d''un vélo électrique d''occasion, 750 euros, état très bon, deux ans d''utilisation, vendu avec deux batteries, retrait uniquement sur place à Nantes.','2026-05-27 17:40:30.246972+02',NULL,'<svg width="100%" viewBox="0 0 680 700" role="img" xmlns="http://www.w3.org/2000/svg"><title>Annonce vente vélo électrique d''occasion</title><desc>Annonce entre particuliers d''un vélo électrique d''occasion à 750 euros à Nantes.</desc><rect x="0" y="0" width="680" height="700" fill="#F4F7FB"/><rect x="20" y="20" width="640" height="660" rx="8" fill="#FFFFFF" stroke="#D5DDE3" stroke-width="1"/><rect x="20" y="20" width="640" height="56" rx="8" fill="#168F5B"/><text x="40" y="56" font-family="Arial, sans-serif" font-size="18" font-weight="700" fill="#FFFFFF">OccaZpro</text><text x="115" y="56" font-family="Arial, sans-serif" font-size="11" fill="#E6F5EC">— ventes entre particuliers</text><text x="600" y="50" text-anchor="end" font-family="Arial, sans-serif" font-size="11" fill="#FFFFFF">📍 Nantes</text><rect x="20" y="76" width="640" height="180" fill="#E8F5EE"/><g transform="translate(280, 110)"><rect x="0" y="60" width="40" height="50" fill="#168F5B"/><circle cx="20" cy="120" r="30" fill="none" stroke="#0F1839" stroke-width="4"/><circle cx="100" cy="120" r="30" fill="none" stroke="#0F1839" stroke-width="4"/><line x1="20" y1="120" x2="100" y2="120" stroke="#0F1839" stroke-width="3"/><line x1="60" y1="120" x2="40" y2="80" stroke="#0F1839" stroke-width="3"/><line x1="60" y1="120" x2="80" y2="80" stroke="#0F1839" stroke-width="3"/><rect x="35" y="70" width="50" height="20" fill="#1E3A8C"/><text x="60" y="84" text-anchor="middle" font-family="Arial, sans-serif" font-size="9" font-weight="700" fill="#FFFFFF">BAT</text></g><g transform="translate(40, 280)"><rect x="0" y="0" width="100" height="24" rx="12" fill="#168F5B"/><text x="50" y="16" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#FFFFFF">Disponible</text><rect x="112" y="0" width="100" height="24" rx="12" fill="#E8ECF8"/><text x="162" y="16" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#1E3A8C">Très bon état</text></g><text x="40" y="340" font-family="Arial, sans-serif" font-size="22" font-weight="700" fill="#0F1839">Vélo électrique Cityride</text><text x="40" y="360" font-family="Arial, sans-serif" font-size="14" fill="#5C6573">Modèle 2023 · 2 ans d''utilisation · acheté 1 400 € neuf</text><text x="40" y="410" font-family="Arial, sans-serif" font-size="36" font-weight="700" fill="#168F5B">750 €</text><text x="200" y="410" font-family="Arial, sans-serif" font-size="13" fill="#5C6573">prix ferme</text><text x="200" y="426" font-family="Arial, sans-serif" font-size="11" font-style="italic" fill="#5C6573">paiement en espèces ou virement</text><line x1="40" y1="450" x2="640" y2="450" stroke="#E0E2E7" stroke-width="1"/><g transform="translate(40, 480)"><text x="0" y="0" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#0F1839">Ce qui est inclus dans la vente</text><text x="0" y="24" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">• Le vélo en bon état général (quelques rayures sur le cadre)</text><text x="0" y="46" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">• <tspan font-weight="700">Deux batteries</tspan> (une d''origine + une achetée en 2024)</text><text x="0" y="68" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">• Le chargeur et la facture d''origine</text><text x="0" y="90" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">• Un antivol U récent (acheté 50 €)</text></g><rect x="40" y="600" width="600" height="56" rx="4" fill="#FDECEB" stroke="#E1372F" stroke-width="1"/><text x="56" y="624" font-family="Arial, sans-serif" font-size="12" font-weight="700" fill="#E1372F">⚠ CONDITIONS DE VENTE</text><text x="56" y="644" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">Retrait <tspan font-weight="700">uniquement sur place à Nantes</tspan>. Pas d''envoi possible. Essai bienvenu.</text></svg>');
INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0021-0000-0000-000000000005','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Carte de fidélité d''une chaîne de boulangeries présentant les avantages : 10% sur les viennoiseries du lundi au vendredi, café offert à partir de 10 visites, exclusivement utilisable en boutique (pas en ligne), valable un an.','2026-05-27 17:40:30.246972+02',NULL,'<svg width="100%" viewBox="0 0 680 480" role="img" xmlns="http://www.w3.org/2000/svg"><title>Carte de fidélité boulangerie</title><desc>Carte de fidélité d''une chaîne de boulangeries avec liste des avantages et restrictions.</desc><rect x="0" y="0" width="680" height="480" fill="#F8F4E8"/><rect x="40" y="40" width="600" height="400" rx="12" fill="#FFFFFF" stroke="#854F0B" stroke-width="2"/><rect x="40" y="40" width="600" height="80" rx="12" fill="#854F0B"/><text x="60" y="78" font-family="Georgia, serif" font-size="24" font-weight="700" fill="#FAEEDA">Boulangerie du Coin</text><text x="60" y="100" font-family="Arial, sans-serif" font-size="12" font-style="italic" fill="#FAEEDA">depuis 1983 · 12 boutiques en France</text><rect x="540" y="60" width="80" height="36" rx="18" fill="#FAEEDA"/><text x="580" y="82" text-anchor="middle" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#854F0B">FIDÉLITÉ</text><text x="60" y="156" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#854F0B">VOTRE CARTE</text><text x="60" y="184" font-family="Georgia, serif" font-size="20" font-weight="700" fill="#0F1839">Mme Camille Lemoine</text><text x="60" y="206" font-family="Arial, sans-serif" font-size="11" fill="#5C6573">N° 4521 · Valable jusqu''au 30 juin de l''année prochaine</text><line x1="60" y1="226" x2="620" y2="226" stroke="#D5C8A8" stroke-width="0.5"/><text x="60" y="254" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#854F0B">VOS AVANTAGES</text><g transform="translate(60, 274)"><circle cx="6" cy="8" r="3" fill="#168F5B"/><text x="20" y="12" font-family="Arial, sans-serif" font-size="13" font-weight="600" fill="#0F1839">−10% sur les viennoiseries du lundi au vendredi</text></g><g transform="translate(60, 298)"><circle cx="6" cy="8" r="3" fill="#168F5B"/><text x="20" y="12" font-family="Arial, sans-serif" font-size="13" font-weight="600" fill="#0F1839">Café offert à partir de 10 visites enregistrées</text></g><g transform="translate(60, 322)"><circle cx="6" cy="8" r="3" fill="#168F5B"/><text x="20" y="12" font-family="Arial, sans-serif" font-size="13" font-weight="600" fill="#0F1839">Invitation aux dégustations privées (2 par an)</text></g><rect x="60" y="350" width="560" height="70" rx="4" fill="#FDECEB" stroke="#E1372F" stroke-width="1"/><text x="76" y="372" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#E1372F">⚠ À NOTER</text><text x="76" y="390" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">Avantages valables <tspan font-weight="700">uniquement en boutique</tspan>, jamais sur les commandes en ligne.</text><text x="76" y="404" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">La réduction ne s''applique pas le week-end ni sur les commandes spéciales.</text></svg>');
INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0021-0000-0000-000000000006','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Capture d''écran d''un site administratif présentant les étapes d''une démarche de demande de carte grise en ligne, avec quatre étapes successives, durée estimée de traitement et liste des pièces nécessaires.','2026-05-27 17:40:30.246972+02',NULL,'<svg width="100%" viewBox="0 0 680 720" role="img" xmlns="http://www.w3.org/2000/svg"><title>Site administratif — demande de carte grise en ligne</title><desc>Capture d''écran d''un site administratif présentant la démarche de demande de carte grise.</desc><rect x="0" y="0" width="680" height="720" fill="#F0F4F8"/><rect x="20" y="20" width="640" height="680" rx="6" fill="#FFFFFF" stroke="#D5DDE3" stroke-width="1"/><rect x="20" y="20" width="640" height="50" fill="#1E3A8C"/><text x="40" y="50" font-family="Arial, sans-serif" font-size="16" font-weight="700" fill="#FFFFFF">DemarchesEnLigne.fr</text><text x="640" y="48" text-anchor="end" font-family="Arial, sans-serif" font-size="10" fill="#A8B0C5">Service officiel</text><rect x="40" y="90" width="600" height="40" rx="4" fill="#F4F8FB"/><text x="56" y="115" font-family="Arial, sans-serif" font-size="13" fill="#5C6573">Accueil  ›  Véhicules  ›  <tspan font-weight="600" fill="#1E3A8C">Demande de carte grise</tspan></text><text x="40" y="170" font-family="Arial, sans-serif" font-size="22" font-weight="700" fill="#0F1839">Demande de carte grise en ligne</text><text x="40" y="194" font-family="Arial, sans-serif" font-size="13" fill="#5C6573">Démarche entièrement dématérialisée — durée estimée du traitement : 7 à 14 jours ouvrés</text><g transform="translate(40, 220)"><rect x="0" y="0" width="600" height="100" rx="6" fill="#FEF5DD" stroke="#A36E0A" stroke-width="1"/><text x="20" y="26" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#A36E0A">📋 PIÈCES À PRÉPARER AVANT DE COMMENCER</text><text x="20" y="50" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">• Pièce d''identité en cours de validité</text><text x="20" y="68" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">• Justificatif de domicile de <tspan font-weight="700">moins de 6 mois</tspan></text><text x="20" y="86" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">• Ancien certificat d''immatriculation (si véhicule d''occasion)</text></g><text x="40" y="354" font-family="Arial, sans-serif" font-size="15" font-weight="700" fill="#0F1839">Étapes de la démarche</text><g transform="translate(40, 380)"><circle cx="20" cy="20" r="20" fill="#168F5B"/><text x="20" y="26" text-anchor="middle" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#FFFFFF">1</text><text x="56" y="20" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#0F1839">Création du dossier en ligne</text><text x="56" y="36" font-family="Arial, sans-serif" font-size="11" fill="#5C6573">durée moyenne : 15 minutes</text></g><line x1="60" y1="420" x2="60" y2="440" stroke="#D5DDE3" stroke-width="1"/><g transform="translate(40, 440)"><circle cx="20" cy="20" r="20" fill="#168F5B"/><text x="20" y="26" text-anchor="middle" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#FFFFFF">2</text><text x="56" y="20" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#0F1839">Téléchargement des pièces justificatives</text><text x="56" y="36" font-family="Arial, sans-serif" font-size="11" fill="#5C6573">format PDF, JPEG ou PNG, 4 Mo maximum par fichier</text></g><line x1="60" y1="480" x2="60" y2="500" stroke="#D5DDE3" stroke-width="1"/><g transform="translate(40, 500)"><circle cx="20" cy="20" r="20" fill="#168F5B"/><text x="20" y="26" text-anchor="middle" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#FFFFFF">3</text><text x="56" y="20" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#0F1839">Paiement sécurisé en ligne</text><text x="56" y="36" font-family="Arial, sans-serif" font-size="11" fill="#5C6573">carte bancaire uniquement, le montant varie selon votre département</text></g><line x1="60" y1="540" x2="60" y2="560" stroke="#D5DDE3" stroke-width="1"/><g transform="translate(40, 560)"><circle cx="20" cy="20" r="20" fill="#1E3A8C"/><text x="20" y="26" text-anchor="middle" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#FFFFFF">4</text><text x="56" y="20" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#0F1839">Réception de la carte grise par courrier</text><text x="56" y="36" font-family="Arial, sans-serif" font-size="11" fill="#5C6573">à votre domicile, sous 7 à 14 jours ouvrés après validation</text></g><rect x="40" y="620" width="600" height="50" rx="4" fill="#E8F5EE"/><text x="56" y="640" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#168F5B">💡 BON À SAVOIR</text><text x="56" y="658" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">Vous pouvez circuler avec un certificat provisoire pendant 1 mois, en attendant la carte définitive.</text></svg>');
INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0022-0000-0000-000000000001','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'SMS de rappel d''un cabinet dentaire pour un rendez-vous prévu le mardi 19 mars à 14h30, avec consigne d''arriver 10 minutes en avance et possibilité d''annuler 24h avant.','2026-05-27 17:40:30.229945+02',NULL,'<svg width="100%" viewBox="0 0 680 580" role="img" xmlns="http://www.w3.org/2000/svg"><title>SMS de rappel rendez-vous dentiste</title><desc>SMS rappelant un rendez-vous dentaire le mardi 19 mars à 14h30.</desc><rect x="0" y="0" width="680" height="580" fill="#F5F5F7"/><rect x="170" y="40" width="340" height="520" rx="36" fill="#1A1A1A"/><rect x="180" y="80" width="320" height="480" rx="4" fill="#FFFFFF"/><rect x="280" y="50" width="120" height="22" rx="11" fill="#1A1A1A"/><text x="200" y="104" font-family="Arial, sans-serif" font-size="13" font-weight="600" fill="#0F1839">9:42</text><g transform="translate(440, 92)"><rect x="0" y="0" width="3" height="8" rx="0.5" fill="#0F1839"/><rect x="5" y="-2" width="3" height="10" rx="0.5" fill="#0F1839"/><rect x="10" y="-4" width="3" height="12" rx="0.5" fill="#0F1839"/><rect x="15" y="-6" width="3" height="14" rx="0.5" fill="#0F1839"/></g><rect x="180" y="120" width="320" height="44" fill="#FAFAFA"/><line x1="180" y1="164" x2="500" y2="164" stroke="#E5E5E7" stroke-width="0.5"/><text x="340" y="147" text-anchor="middle" font-family="Arial, sans-serif" font-size="15" font-weight="600" fill="#0F1839">Cabinet Dr Martin</text><g transform="translate(340, 195)"><circle cx="0" cy="0" r="24" fill="#1E3A8C"/><text x="0" y="6" text-anchor="middle" font-family="Arial, sans-serif" font-size="18" font-weight="700" fill="#FFFFFF">+</text></g><text x="340" y="240" text-anchor="middle" font-family="Arial, sans-serif" font-size="13" font-weight="600" fill="#0F1839">Cabinet Dr Martin</text><text x="340" y="256" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" fill="#888888">SMS · Aujourd''hui</text><rect x="200" y="285" width="270" height="200" rx="14" fill="#E8E8ED"/><text x="216" y="310" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">Bonjour Mme Petit,</text><text x="216" y="334" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">Rappel de votre rendez-vous</text><text x="216" y="352" font-family="Arial, sans-serif" font-size="12" font-weight="700" fill="#1E3A8C">mardi 19 mars à 14h30</text><text x="216" y="370" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">avec le Dr Martin.</text><text x="216" y="396" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">Merci d''arriver</text><text x="216" y="414" font-family="Arial, sans-serif" font-size="12" font-weight="700" fill="#0F1839">10 minutes en avance</text><text x="216" y="432" font-family="Arial, sans-serif" font-size="12" fill="#0F1839">pour les formalités.</text><text x="216" y="458" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">Annulation possible jusqu''à</text><text x="216" y="473" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">24h avant : 01 23 45 67 89</text><text x="340" y="510" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" fill="#888888">Hier · 18:32</text></svg>');
INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0022-0000-0000-000000000002','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Affiche de promotion du supermarché annonçant trois produits en promo cette semaine : tomates à 1,50€/kg, lait 2 euros le pack de 6, pain de mie 1,80 euros au lieu de 2,50 euros.','2026-05-27 17:40:30.229945+02',NULL,'<svg width="100%" viewBox="0 0 680 600" role="img" xmlns="http://www.w3.org/2000/svg"><title>Affiche promo supermarché</title><desc>Promotion de la semaine au supermarché : tomates, lait et pain de mie en réduction.</desc><rect x="0" y="0" width="680" height="600" fill="#FDECEB"/><rect x="40" y="40" width="600" height="520" fill="#FFFFFF" stroke="#E1372F" stroke-width="3"/><rect x="40" y="40" width="600" height="80" fill="#E1372F"/><text x="340" y="80" text-anchor="middle" font-family="Georgia, serif" font-size="28" font-weight="700" fill="#FFFFFF">SUPER PROMO</text><text x="340" y="105" text-anchor="middle" font-family="Arial, sans-serif" font-size="14" fill="#FFFFFF">Cette semaine au Marché du Coin</text><text x="340" y="160" text-anchor="middle" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#0F1839">Du lundi au samedi</text><g transform="translate(70, 200)"><rect x="0" y="0" width="170" height="180" fill="#E8F5EE" stroke="#168F5B" stroke-width="2"/><g transform="translate(85, 50)"><circle cx="0" cy="0" r="30" fill="#E1372F"/><circle cx="-10" cy="-8" r="3" fill="#FFFFFF" opacity="0.5"/><path d="M -5 -22 L 0 -28 L 5 -22" fill="#168F5B" stroke="#0F1839" stroke-width="1"/></g><text x="85" y="120" text-anchor="middle" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#0F1839">Tomates</text><text x="85" y="138" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" fill="#5C6573">au kilo</text><text x="85" y="166" text-anchor="middle" font-family="Arial, sans-serif" font-size="22" font-weight="700" fill="#E1372F">1,50 €</text></g><g transform="translate(255, 200)"><rect x="0" y="0" width="170" height="180" fill="#E8ECF8" stroke="#1E3A8C" stroke-width="2"/><g transform="translate(85, 50)"><rect x="-25" y="-30" width="50" height="55" fill="#FFFFFF" stroke="#1E3A8C" stroke-width="2"/><rect x="-25" y="-30" width="50" height="12" fill="#1E3A8C"/><text x="0" y="-20" text-anchor="middle" font-family="Arial, sans-serif" font-size="7" font-weight="700" fill="#FFFFFF">LAIT</text><text x="0" y="-5" text-anchor="middle" font-family="Arial, sans-serif" font-size="8" font-weight="700" fill="#1E3A8C">×6</text></g><text x="85" y="120" text-anchor="middle" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#0F1839">Lait demi-écrémé</text><text x="85" y="138" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" fill="#5C6573">pack de 6 bouteilles</text><text x="85" y="166" text-anchor="middle" font-family="Arial, sans-serif" font-size="22" font-weight="700" fill="#1E3A8C">2,00 €</text></g><g transform="translate(440, 200)"><rect x="0" y="0" width="170" height="180" fill="#FEF5DD" stroke="#A36E0A" stroke-width="2"/><g transform="translate(85, 50)"><rect x="-30" y="-15" width="60" height="35" fill="#E8A317" stroke="#0F1839" stroke-width="1.5"/><rect x="-30" y="-15" width="60" height="6" fill="#A36E0A"/></g><text x="85" y="120" text-anchor="middle" font-family="Arial, sans-serif" font-size="14" font-weight="700" fill="#0F1839">Pain de mie</text><text x="85" y="138" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" fill="#5C6573">grand format 500g</text><g transform="translate(50, 158)"><text x="0" y="0" font-family="Arial, sans-serif" font-size="13" fill="#888888" text-decoration="line-through">2,50 €</text><text x="36" y="0" font-family="Arial, sans-serif" font-size="22" font-weight="700" fill="#A36E0A">1,80 €</text></g></g><rect x="100" y="420" width="480" height="60" rx="6" fill="#E1372F"/