INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0022-0000-0000-000000000003','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Panneau d''horaires d''ouverture d''un bureau de poste : ouvert du lundi au vendredi de 9h à 12h30 et de 14h à 18h, samedi matin de 9h à 12h, fermé le dimanche.','2026-05-27 17:40:30.229945+02',NULL,'<svg width="100%" viewBox="0 0 680 540" role="img" xmlns="http://www.w3.org/2000/svg"><title>Horaires bureau de poste</title><desc>Panneau d''horaires d''ouverture d''un bureau de poste.</desc><rect x="0" y="0" width="680" height="540" fill="#FEF5DD"/><rect x="60" y="40" width="560" height="460" rx="8" fill="#FFFFFF" stroke="#1E3A8C" stroke-width="3"/><rect x="60" y="40" width="560" height="80" fill="#FFCD00"/><text x="340" y="80" text-anchor="middle" font-family="Georgia, serif" font-size="26" font-weight="700" fill="#1E3A8C">BUREAU DE POSTE</text><text x="340" y="105" text-anchor="middle" font-family="Arial, sans-serif" font-size="13" fill="#0F1839">Place de la République · 75011 Paris</text><text x="340" y="160" text-anchor="middle" font-family="Arial, sans-serif" font-size="15" font-weight="700" fill="#1E3A8C">HORAIRES D''OUVERTURE</text><line x1="240" y1="170" x2="440" y2="170" stroke="#FFCD00" stroke-width="3"/><g transform="translate(120, 200)"><line x1="0" y1="0" x2="440" y2="0" stroke="#0F1839" stroke-width="0.5"/><text x="0" y="32" font-family="Arial, sans-serif" font-size="16" font-weight="600" fill="#0F1839">Lundi — Vendredi</text><text x="240" y="32" font-family="Arial, sans-serif" font-size="15" font-weight="700" fill="#168F5B">9h — 12h30</text><text x="370" y="32" font-family="Arial, sans-serif" font-size="13" fill="#5C6573">et</text><text x="395" y="32" font-family="Arial, sans-serif" font-size="15" font-weight="700" fill="#168F5B">14h — 18h</text><line x1="0" y1="52" x2="440" y2="52" stroke="#0F1839" stroke-width="0.5"/><text x="0" y="86" font-family="Arial, sans-serif" font-size="16" font-weight="600" fill="#0F1839">Samedi</text><text x="240" y="86" font-family="Arial, sans-serif" font-size="15" font-weight="700" fill="#168F5B">9h — 12h</text><text x="350" y="86" font-family="Arial, sans-serif" font-size="11" font-style="italic" fill="#5C6573">(matin uniquement)</text><line x1="0" y1="106" x2="440" y2="106" stroke="#0F1839" stroke-width="0.5"/><text x="0" y="140" font-family="Arial, sans-serif" font-size="16" fill="#7A8794">Dimanche</text><text x="240" y="140" font-family="Arial, sans-serif" font-size="15" font-weight="700" fill="#E1372F">FERMÉ</text><line x1="0" y1="160" x2="440" y2="160" stroke="#0F1839" stroke-width="0.5"/></g><rect x="120" y="400" width="440" height="60" rx="4" fill="#FFCD00"/><text x="340" y="425" text-anchor="middle" font-family="Arial, sans-serif" font-size="13" font-weight="700" fill="#1E3A8C">JOURS FÉRIÉS : FERMETURE EXCEPTIONNELLE</text><text x="340" y="445" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">Boîte aux lettres extérieure accessible 24h/24</text></svg>');
INSERT INTO medias (id, type, url, storage_key, original_filename, content_type, size_bytes, duration_sec, alt_text, created_at, transcript, inline_svg) VALUES ('33333333-0022-0000-0000-000000000004','IMAGE',NULL,NULL,NULL,NULL,NULL,NULL,'Conversation WhatsApp dans laquelle Julie écrit à son amie pour annuler le dîner du samedi soir car elle est malade, et propose de se voir le week-end suivant.','2026-05-27 17:40:30.229945+02',NULL,'<svg width="100%" viewBox="0 0 680 760" role="img" xmlns="http://www.w3.org/2000/svg"><title>Conversation WhatsApp annulation dîner</title><desc>Conversation WhatsApp où Julie annule un dîner pour cause de maladie.</desc><rect x="0" y="0" width="680" height="760" fill="#F5F5F7"/><rect x="170" y="40" width="340" height="700" rx="36" fill="#1A1A1A"/><rect x="180" y="80" width="320" height="660" rx="4" fill="#ECE5DD"/><rect x="280" y="50" width="120" height="22" rx="11" fill="#1A1A1A"/><rect x="180" y="80" width="320" height="60" fill="#075E54"/><text x="200" y="105" font-family="Arial, sans-serif" font-size="14" font-weight="600" fill="#FFFFFF">9:42</text><g transform="translate(440, 96)"><rect x="0" y="0" width="3" height="8" rx="0.5" fill="#FFFFFF"/><rect x="5" y="-2" width="3" height="10" rx="0.5" fill="#FFFFFF"/><rect x="10" y="-4" width="3" height="12" rx="0.5" fill="#FFFFFF"/><rect x="15" y="-6" width="3" height="14" rx="0.5" fill="#FFFFFF"/></g><rect x="180" y="140" width="320" height="60" fill="#128C7E"/><g transform="translate(195, 158)"><path d="M 6 0 L 0 8 L 6 16" fill="none" stroke="#FFFFFF" stroke-width="2"/></g><g transform="translate(220, 158)"><circle cx="12" cy="12" r="12" fill="#FFCD00"/><text x="12" y="17" text-anchor="middle" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#0F1839">J</text></g><text x="252" y="174" font-family="Arial, sans-serif" font-size="14" font-weight="600" fill="#FFFFFF">Julie</text><text x="252" y="190" font-family="Arial, sans-serif" font-size="11" fill="#A8E0D8">en ligne</text><g transform="translate(200, 220)"><rect x="0" y="0" width="220" height="60" rx="8" fill="#FFFFFF"/><path d="M 0 8 L -8 0 L 0 0 Z" fill="#FFFFFF"/><text x="14" y="22" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">Salut ma belle ! Toujours OK</text><text x="14" y="38" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">pour samedi soir ? 😊</text><text x="200" y="54" text-anchor="end" font-family="Arial, sans-serif" font-size="9" fill="#888888">10:14</text></g><g transform="translate(260, 295)"><rect x="0" y="0" width="220" height="80" rx="8" fill="#DCF8C6"/><path d="M 220 8 L 228 0 L 220 0 Z" fill="#DCF8C6"/><text x="14" y="22" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">Coucou 😷</text><text x="14" y="40" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">Justement je t''écrivais...</text><text x="14" y="58" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">Je suis malade depuis hier,</text><text x="14" y="74" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">je préfère annuler ce soir.</text><text x="190" y="76" font-family="Arial, sans-serif" font-size="8" fill="#666666">10:31 ✓✓</text></g><g transform="translate(260, 390)"><rect x="0" y="0" width="220" height="60" rx="8" fill="#DCF8C6"/><text x="14" y="22" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">Je suis vraiment désolée 😞</text><text x="14" y="40" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">On peut peut-être se voir</text><text x="14" y="58" font-family="Arial, sans-serif" font-size="11" font-weight="700" fill="#0F1839">le week-end prochain ?</text><text x="190" y="58" font-family="Arial, sans-serif" font-size="8" fill="#666666">10:32 ✓✓</text></g><g transform="translate(200, 465)"><rect x="0" y="0" width="220" height="40" rx="8" fill="#FFFFFF"/><path d="M 0 8 L -8 0 L 0 0 Z" fill="#FFFFFF"/><text x="14" y="20" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">Oh non ! Soigne-toi bien 💕</text><text x="14" y="35" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">Pas de souci pour samedi prochain</text><text x="200" y="33" text-anchor="end" font-family="Arial, sans-serif" font-size="9" fill="#888888">10:33</text></g><g transform="translate(200, 520)"><rect x="0" y="0" width="200" height="40" rx="8" fill="#FFFFFF"/><text x="14" y="20" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">Je passe à la pharmacie</text><text x="14" y="35" font-family="Arial, sans-serif" font-size="11" fill="#0F1839">si tu as besoin de quelque chose</text></g><rect x="190" y="700" width="290" height="34" rx="17" fill="#FFFFFF" stroke="#D5D5D5" stroke-width="0.5"/><text x="208" y="722" font-family="Arial, sans-serif" font-size="12" fill="#888888">Message</text></svg>');
